import type { FC, ReactNode } from 'react';
import { motion } from 'framer-motion';
import ToolsSidebar from './ToolsSidebar';

interface ToolLayoutProps {
  title: string;
  description: string;
  /** Rendered inline alongside the description (e.g. a share/export button) instead
   * of its own row — keeps a one-off action from costing a whole extra line of height. */
  headerAction?: ReactNode;
  children: ReactNode;
}

// Shared shell for every individual tool page: a persistent left-hand tool
// switcher (ToolsSidebar) plus a heading, styled to match the rest of the
// site's page headers (Projects, Certifications). Future tools wrap their
// page content in this instead of rebuilding the header/nav.
// pt-24 clears the fixed navbar — every top-level page in the app carries this
// same offset (see pages/Certifications.tsx, pages/Experience.tsx, etc.).
const ToolLayout: FC<ToolLayoutProps> = ({ title, description, headerAction, children }) => {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="pt-24"
    >
      <section className="section-container pb-16 md:pb-20">
        <div className="max-w-6xl mx-auto flex flex-col md:flex-row gap-6 md:gap-10 items-start">
          <ToolsSidebar />

          <div className="flex-1 min-w-0 w-full">
            <div className="mb-6 md:mb-8">
              <h1 className="text-2xl md:text-3xl font-display font-medium mb-2 text-accent">
                {title}
              </h1>
              <div className="flex items-center justify-between gap-4 flex-wrap">
                <p className="text-muted-foreground max-w-2xl text-base md:text-lg font-light leading-relaxed">
                  {description}
                </p>
                {headerAction && <div className="shrink-0">{headerAction}</div>}
              </div>
            </div>

            {children}
          </div>
        </div>
      </section>
    </motion.div>
  );
};

export default ToolLayout;
