import type { FC } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { ArrowLeft } from 'lucide-react';
import { tools, getToolPath, getToolsBasePath } from '@/data/tools';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

// Persistent tool switcher shown alongside every individual tool page, so
// users don't have to go back to /tools to try another one. Renders as a
// left column on desktop; on mobile it collapses to a single compact
// dropdown instead of a horizontally-scrolling row (which had no visible
// scrollbar affordance and was easy to miss on a phone).
const ToolsSidebar: FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const basePath = getToolsBasePath(location.pathname);
  const activeTool = tools.find(
    (tool) => tool.status === 'available' && location.pathname === getToolPath(tool.slug, basePath)
  );

  return (
    <>
      <div className="flex md:hidden items-center gap-2 w-full">
        <Link
          to={basePath}
          aria-label="All tools"
          className="flex items-center justify-center h-10 w-10 shrink-0 rounded-md border border-input text-muted-foreground hover:text-accent hover:border-accent/40 transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
        </Link>

        <Select
          value={activeTool?.slug}
          onValueChange={(slug) => navigate(getToolPath(slug, basePath))}
        >
          <SelectTrigger aria-label="Switch tool" className="flex-1">
            <SelectValue placeholder="Choose a tool">
              {activeTool?.title}
            </SelectValue>
          </SelectTrigger>
          <SelectContent>
            {tools.map((tool) => (
              <SelectItem key={tool.slug} value={tool.slug} disabled={tool.status !== 'available'}>
                <span className="flex items-center gap-2.5">
                  <tool.icon className="w-4 h-4 shrink-0" />
                  {tool.title}
                  {tool.status !== 'available' && (
                    <span className="text-xs text-muted-foreground">(soon)</span>
                  )}
                </span>
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <nav aria-label="Tools" className="hidden md:flex md:flex-col gap-1.5 md:w-56 shrink-0">
        <Link
          to={basePath}
          className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm text-muted-foreground hover:text-accent hover:bg-accent/5 transition-colors shrink-0 whitespace-nowrap"
        >
          <ArrowLeft className="w-4 h-4" />
          All tools
        </Link>

        <div className="h-px bg-border my-1.5" />

        {tools.map((tool) => {
          const Icon = tool.icon;
          const isAvailable = tool.status === 'available';
          const isActive = isAvailable && location.pathname === getToolPath(tool.slug, basePath);
          const itemClasses = `flex items-center gap-2.5 px-3 py-2 rounded-lg text-sm font-medium whitespace-nowrap shrink-0 transition-colors ${
            isActive
              ? 'bg-accent/15 text-accent'
              : isAvailable
                ? 'text-foreground/70 hover:text-foreground hover:bg-accent/5'
                : 'text-muted-foreground/40 cursor-not-allowed'
          }`;

          if (!isAvailable) {
            return (
              <div key={tool.slug} className={itemClasses} aria-disabled="true">
                <Icon className="w-4 h-4 shrink-0" />
                {tool.title}
              </div>
            );
          }

          return (
            <Link
              key={tool.slug}
              to={getToolPath(tool.slug, basePath)}
              aria-current={isActive ? 'page' : undefined}
              className={itemClasses}
            >
              <Icon className="w-4 h-4 shrink-0" />
              {tool.title}
            </Link>
          );
        })}
      </nav>
    </>
  );
};

export default ToolsSidebar;
